def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Compute opponent cooperation rate and last actions
    opp_c = 0
    for _, o in history:
        if o == 'C':
            opp_c += 1
    opp_rate = opp_c / n

    last_me, last_opp = history[-1]

    # Detect length of opponent's current cooperation streak
    c_streak = 0
    for _, o in reversed(history):
        if o == 'C':
            c_streak += 1
        else:
            break

    # Detect length of opponent's current defection streak
    d_streak = 0
    for _, o in reversed(history):
        if o == 'D':
            d_streak += 1
        else:
            break

    # Detect mutual cooperation streak
    cc_streak = 0
    for a, b in reversed(history):
        if a == 'C' and b == 'C':
            cc_streak += 1
        else:
            break

    # Detect mutual defection streak
    dd_streak = 0
    for a, b in reversed(history):
        if a == 'D' and b == 'D':
            dd_streak += 1
        else:
            break

    remaining = 100 - n

    # Endgame: last 2 rounds — defect if opponent likely to cooperate.
    # Avoid DC loss late by cooperating when opponent will defect.
    if remaining <= 1:
        if opp_rate >= 0.5 and c_streak >= 1:
            return 'D'
        if last_opp == 'D':
            return 'D'
        return 'C'

    if remaining <= 3:
        # If opponent has been very cooperative recently, exploit
        if c_streak >= 3 and opp_rate >= 0.6:
            return 'D'
        if last_opp == 'D':
            return 'D'
        if opp_rate >= 0.6:
            return 'C'
        return 'D'

    # Sustained defector detection: defect back hard, rarely probe
    if d_streak >= 2 or (opp_rate < 0.3 and n >= 6):
        # If opponent usually defects and has long defection streak, defect
        if rng.random() < 0.06:
            return 'C'
        return 'D'

    # Recover from mutual defection spiral: try C after a few DD rounds
    if dd_streak >= 2:
        if rng.random() < 0.35:
            return 'C'
        return 'D'

    # Very cooperative opponent: cooperate to keep 3/round, rare probes
    if opp_rate >= 0.9 and d_streak == 0:
        if n >= 25 and rng.random() < 0.02:
            return 'D'
        return 'C'

    # If we just defected and opponent still cooperated, return to C (avoid alienating a nice opponent)
    if last_me == 'D' and last_opp == 'C':
        return 'C'

    # Tit-for-tat with forgiveness
    if last_opp == 'D':
        # Isolated defection: forgive with probability to restore CC
        if d_streak == 1 and opp_rate >= 0.5:
            if rng.random() < 0.35:
                return 'C'
            return 'D'
        # Opponent mixed: retaliate
        return 'D'

    # last_opp == 'C'
    # If opponent cooperates, cooperate, but occasionally probe a bit late
    if c_streak >= 4 and n >= 15 and opp_rate >= 0.55:
        if rng.random() < 0.04:
            return 'D'
    return 'C'
